extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var scene := await instantiate_scene("res://ui/gallery_screen.tscn")
	if not check("scene_exists", scene != null, "La scena ui/gallery_screen.tscn deve caricarsi ed essere istanziabile"):
		return
	var grid := find_by_name(scene, "GridContainer") as GridContainer
	if not check("grid_exists", grid != null, "Nella scena deve esserci un GridContainer di nome GridContainer"):
		return
	if not check("has_pop", has_function(scene, "populate_gallery"), "Lo script deve definire la funzione populate_gallery()"):
		return
	if not check("has_count", has_function(scene, "get_unlocked_count"), "Lo script deve definire la funzione get_unlocked_count() -> int"):
		return

	if UnlockManager:
		UnlockManager.unlocked_images.clear()

	scene.call("populate_gallery")
	var initial_count: int = scene.call("get_unlocked_count")
	check("initial_zero", initial_count == 0, "Senza illustrazioni sbloccate get_unlocked_count() deve restituire 0 (restituisce %d)" % initial_count)

	var child_count: int = grid.get_child_count()
	check("children_created", child_count >= 2, "GridContainer deve contenere un figlio per ciascuna voce del catalogo (ne ha %d)" % child_count)

	if UnlockManager:
		UnlockManager.unlock_image("bg_archivio")

	scene.call("populate_gallery")
	var updated_count: int = scene.call("get_unlocked_count")
	check("one_unlocked", updated_count == 1, "Dopo aver sbloccato 'bg_archivio', get_unlocked_count() deve restituire 1 (restituisce %d)" % updated_count)

