class_name GalleryScreen
extends Control

@onready var grid_container: GridContainer = $GridContainer

const GALLERY_CATALOG: Array[Dictionary] = [
	{
		"id": "bg_archivio",
		"title": "L'Archivio",
		"texture_path": "res://assets/sprites/background.png"
	},
	{
		"id": "player_sprite",
		"title": "Elena",
		"texture_path": "res://assets/sprites/player.png"
	}
]


func _ready() -> void:
	populate_gallery()


func populate_gallery() -> void:
	if not grid_container:
		return

	for child in grid_container.get_children():
		child.queue_free()

	for item in GALLERY_CATALOG:
		var item_id: String = String(item.get("id", ""))
		var item_title: String = String(item.get("title", ""))
		var texture_path: String = String(item.get("texture_path", ""))

		var card := VBoxContainer.new()

		var tex_rect := TextureRect.new()
		tex_rect.custom_minimum_size = Vector2(128, 128)
		tex_rect.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
		tex_rect.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED

		var label := Label.new()

		if UnlockManager and UnlockManager.is_image_unlocked(item_id):
			if FileAccess.file_exists(texture_path):
				tex_rect.texture = load(texture_path) as Texture2D
			label.text = item_title
		else:
			tex_rect.modulate = Color(0.1, 0.1, 0.1, 1.0)
			label.text = "???"

		card.add_child(tex_rect)
		card.add_child(label)
		grid_container.add_child(card)


func get_unlocked_count() -> int:
	var count := 0
	for item in GALLERY_CATALOG:
		var item_id: String = String(item.get("id", ""))
		if UnlockManager and UnlockManager.is_image_unlocked(item_id):
			count += 1
	return count

